function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  validation: ValidationResult,
  sessionStore?: SessionStore,
  history?: HistoryOptions
): void {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') {
    handlePing(ws, message.timestamp);
    return;
  }
  if (message.type === 'list_sessions') {
    handleListSessions(ws, session, message, sessionStore, history);
  }
}

async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  message: {type: 'list_sessions'; limit?: number; before?: unknown},
  sessionStore?: SessionStore,
  history?: HistoryOptions
): Promise<void> {
  if (!history?.enabled) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'History is not enabled');
    return;
  }

  if (!sessionStore || !sessionStore.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Session store does not support listing conversations');
    return;
  }

  try {
    const summaries = await sessionStore.listFor(session.userId, {
      limit: message.limit,
      before: message.before as unknown,
    });
    const sessions = summaries.map(s => ({
      sessionId: s.sessionId,
      createdAt: s.createdAt instanceof Date ? s.createdAt.toISOString() : s.createdAt,
      updatedAt: s.updatedAt instanceof Date ? s.updatedAt.toISOString() : s.updatedAt,
      entryCount: s.entryCount,
    }));
    sendJson(ws, {type: 'session_list', sessions});
  } catch (error) {
    log.error('ws', 'failed to list sessions', {
      sessionId: session.sessionId,
      userId: session.userId,
      error: error instanceof Error ? error.message : 'Unknown error',
    });
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to retrieve conversation list');
  }
}

